using System; using System.Collections.Generic; using System.IO; using System.IO.Compression; using System.Xml.Linq; using CalcRapido;
class P { static int ok,bad; static void C(string n,bool v,string d){if(v){ok++;Console.WriteLine("OK  "+n);}else{bad++;Console.WriteLine("BAD "+n+" "+d);}}
static void Main(){
 Workbook wb=new Workbook(); Sheet s=wb.Sheets[0]; s.SetTextLiteral(0,0,"Color"); s.SetTextLiteral(1,0,"Rojo"); s.SetTextLiteral(2,0,"Azul");
 DataValidationRule r=new DataValidationRule{Row1=1,Col1=0,Row2=2,Col2=0}; r.Items.Add("Rojo");r.Items.Add("Azul");s.Validations.Add(r);
 wb.Recalculate(); string x="tests/bin/feature.xlsx"; XlsxIO.SaveNew(wb,x); string xml; using(ZipArchive z=ZipFile.OpenRead(x)){using(var sr=new StreamReader(z.GetEntry("xl/worksheets/sheet1.xml").Open()))xml=sr.ReadToEnd();}
 C("validación en xlsx",xml.Contains("dataValidations")&&xml.Contains("Rojo"),"xml"); Workbook n=XlsxIO.Load(x); // loader may not parse validation but load
 C("xlsx recarga",n.Sheets[0].GetCell(1,0).Value.Text=="Rojo","value");
 C("validación recargada",n.Sheets[0].Validations.Count>0,"count");
 s.AutoFilterRef="A1:B2"; XlsxIO.SaveNew(wb,"tests/bin/filter.xlsx"); Workbook fx=XlsxIO.Load("tests/bin/filter.xlsx"); C("autofiltro xlsx",fx.Sheets[0].AutoFilterRef=="A1:B2",fx.Sheets[0].AutoFilterRef);
 string crb="tests/bin/feature.crb"; FileIO.SaveNative(wb,crb); Workbook c=FileIO.LoadNative(crb); C("validación en crb",c.Sheets[0].Validations.Count==1,"count");
 string adv="tests/bin/advanced.xlsx";
 if(File.Exists(adv)){ Workbook ai=XlsxIO.Load(adv); string icrb="tests/bin/image.crb"; FileIO.SaveNative(ai,icrb); Workbook ic=FileIO.LoadNative(icrb); bool has=false; foreach(Sheet sh in ic.Sheets) if(sh.Images.Count>0) has=true; C("imagen en crb",has,"sin imagen"); }
 string strict="tests/bin/feature-strict.xlsx"; XlsxIO.SaveStrict(wb,strict); Workbook st=XlsxIO.Load(strict); C("strict recarga",st.Sheets[0].GetCell(2,0).Value.Text=="Azul","value");
 using(ZipArchive z=ZipFile.OpenRead(strict)){using(var sr=new StreamReader(z.GetEntry("xl/workbook.xml").Open()))xml=sr.ReadToEnd();} C("strict namespace",xml.Contains("purl.oclc.org/ooxml/spreadsheetml"),"ns");
 try { Workbook sp=XlsxIO.Load("tests/corpus/SimpleStrict.xlsx"); XlsxIO.Save(sp,"tests/bin/strict-preserved.xlsx"); Workbook spr=XlsxIO.Load("tests/bin/strict-preserved.xlsx"); C("strict conserva estructura",spr.Sheets.Count>=1,"sheets"); } catch(Exception ex){ C("strict conserva estructura",false,ex.Message); }
 try { Workbook ft=new Workbook(); Sheet fs=ft.Sheets[0]; fs.SetNumber(0,0,21); fs.SetInput(1,0,"=A1*2"); fs.SetInput(2,0,"=FORMULATEXT(A2)"); ft.Recalculate(); C("FORMULATEXT",fs.GetCell(2,0).Value.Text=="=A1*2",fs.GetCell(2,0).Value.Text); } catch(Exception ex){ C("FORMULATEXT",false,ex.Message); }
 try { Workbook sw=new Workbook(); Sheet ss=sw.Sheets[0]; ss.SetTextLiteral(0,0,"Comprado"); ss.SetNumber(0,1,10); ss.SetTextLiteral(1,0,"No comprado"); ss.SetNumber(1,1,20); ss.SetTextLiteral(2,0,"Comprado"); ss.SetNumber(2,1,30); ss.SetInput(0,2,"=SUMIF(A1:A3,\"Comprado\",B1:B3)"); sw.Recalculate(); C("SUMIF rango suma",ss.GetCell(0,2).Value.Number==40,ss.GetCell(0,2).Value.ToDisplayString()); } catch(Exception ex){ C("SUMIF rango suma",false,ex.Message); }
 try { Workbook aw=new Workbook(); Sheet asheet=aw.Sheets[0]; asheet.SetInput(0,0,"=INDEX({\"Do\";\"Lu\";\"Ma\"},2)"); aw.Recalculate(); C("constante matricial",asheet.GetCell(0,0).Value.Text=="Lu",asheet.GetCell(0,0).Value.ToDisplayString()); } catch(Exception ex){ C("constante matricial",false,ex.Message); }
 try { Workbook dy=new Workbook(); Sheet ds=dy.Sheets[0]; ds.SetInput(0,0,"=SEQUENCE(2;2;1;1)"); dy.Recalculate(); C("derrame dynamic array",ds.GetCell(1,1).Value.Kind==ValueKind.Number&&ds.GetCell(1,1).Value.Number==4,ds.GetCell(1,1).Value.ToDisplayString()); } catch(Exception ex){ C("derrame dynamic array",false,ex.Message); }
 try { C("hash de protección", Sheet.ExcelPasswordHash("test")=="CBEB", Sheet.ExcelPasswordHash("test")); } catch(Exception ex){ C("hash de protección",false,ex.Message); }
 try { Workbook tw=new Workbook(); Sheet ts=tw.Sheets[0]; TableFormat tf=new TableFormat{Row1=0,Col1=0,Row2=1,Col2=1,HeaderRows=1}; ts.TableFormats.Add(tf); ts.SetInput(2,0,"nuevo"); C("tabla se amplía",tf.Row2==2,tf.Row2.ToString()); } catch(Exception ex){ C("tabla se amplía",false,ex.Message); }
 try { Workbook pw=new Workbook(); Sheet ps=pw.Sheets[0]; PivotRange pr=new PivotRange{Row1=0,Col1=0,Row2=8,Col2=3,RowField=0,RowCaption="Cat"}; PivotCache pc=new PivotCache(); pc.FieldNames.Add("Cat"); pc.FieldNames.Add("Valor"); pc.Rows.Add(new List<CellValue>{CellValue.FromText("A"),CellValue.FromNumber(10)}); pc.Rows.Add(new List<CellValue>{CellValue.FromText("A"),CellValue.FromNumber(5)}); pr.Cache=pc; pr.DataFields.Add(1); pr.DataNames.Add("Suma"); C("tabla dinámica refresca",PivotEngine.Refresh(ps,pr)&&ps.GetCell(1,1).Value.Number==15,ps.GetCell(1,1).Value.ToDisplayString()); } catch(Exception ex){ C("tabla dinámica refresca",false,ex.Message); }
 try { Workbook hw=new Workbook(); Sheet hs=hw.Sheets[0]; hs.SetInput(0,0,"=HSTACK({1;2};{3;4})"); hw.Recalculate(); C("HSTACK",hs.GetCell(0,0).Value.ToDisplayString()=="1"&&hs.GetCell(0,1).Value.ToDisplayString()=="3"&&hs.GetCell(1,1).Value.ToDisplayString()=="4","valores"); } catch(Exception ex){ C("HSTACK",false,ex.Message); }
 try { Workbook vw=new Workbook(); Sheet vs=vw.Sheets[0]; vs.SetInput(0,0,"=VSTACK({1,2};{3,4})"); vw.Recalculate(); C("VSTACK",vs.GetCell(1,0).Value.ToDisplayString()=="3"&&vs.GetCell(0,1).Value.ToDisplayString()=="2","valores"); } catch(Exception ex){ C("VSTACK",false,ex.Message); }
 Console.WriteLine("Features: "+ok+" correctas, "+bad+" fallidas."); Environment.Exit(bad==0?0:1);
}}
